#include <stdint.h>
#include "stm32f7xx.h"

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif



void initializePins();
int translateCharacter(char);
void flashSegment(char);
void flashDisplay(char*);
void simple_delay(uint32_t count);


int main(void)
{



	initializePins();


	char randomLetters[] = "abcd";
	char secondRandomLetters[] = "dcba";

    /* Loop forever */
	while(1) {
		simple_delay((uint32_t) 1000000);
		flashDisplay(randomLetters);
		simple_delay((uint32_t) 1000000);
		flashDisplay(secondRandomLetters);
	}

	return 0;
}



void initializePins()
{

	// Initializing the clocks for ports A, B, G, H, I
	RCC->AHB1ENR = RCC->AHB1ENR |= 0b111000011;

	// Initialization for 7-segment display pins (D2-D8 = A-G)

	// Initializes D5 as push-pull
	GPIOA->MODER &= 0;
	GPIOA->MODER |= 0xA8000000;
	GPIOA->MODER |= (0b01 << (2 * 8));
	GPIOA->OTYPER &= 0;

	// Initializes D3 as push-pull
	GPIOB->MODER &= 0;
	GPIOB->MODER |= 0X00000280;
	GPIOB->MODER |= (0b01 << (2 * 4));
	GPIOB->OTYPER &= 0;

	// Initializes D2 and D4 as push-pull
	GPIOG->MODER &= 0;
	GPIOG->MODER |= (0b0101 << (6 * 2));
	GPIOG->OTYPER &= 0;

	// Initializes D6 as push-pull
	GPIOH->MODER &= 0;
	GPIOH->MODER |= (0b01 << (6 * 2));
	GPIOH->OTYPER &=0;

	// Initializes D7 and D8 as push-pull pins
	GPIOI->MODER &= 0;
	GPIOI->MODER |= (0b0101 << 2);
	GPIOI->OTYPER &= 0;


	// Initialization for digit selection (D10-D13).
	// I am not clearing out the registers because it was already done above when
	// initializing the 7-segment pins
	GPIOI->MODER |= 0B0101; // Initializes D10 and D13

	GPIOB->MODER |= (0b0101 << (2 * 14)); // initializes D11 and D12
}

void flashDisplay(char *theString) {

	// Flashes segment 1
	flashSegment(*theString);

	// turns on segment 1. Reset should happen during the flashSegment function
	GPIOI->ODR |= 1;

	// Flashes segment 2
	flashSegment(*(++theString));

	GPIOB->ODR |= (0b1 << 15);

	// Flashes segment 3
	flashSegment(*(++theString));

	GPIOB->ODR |= (0b1 << 14);

	// Flashes segment 4
	flashSegment(*(++theString));

	GPIOI->ODR |= (0b1 <<1);
}

void flashSegment(char theCharacter) // possibly add code to turn lights on and off
{
	int segmentCode = translateCharacter(theCharacter);

	// Assigns bit 0 in the 7-segment display sequence to Segment A (D2 on the board, PG6 on the processor)
	GPIOG->ODR = 0 | ((segmentCode & 0b1) << 6);

	// Assigns bit 1 in the 7-segment display sequence to Segment B (D3 on the board, PB4 on the processor)
	GPIOB->ODR = ((segmentCode & 0b10 >> 1) << 4);

	// Assigns bit 2 in the 7-segment display sequence to Segment C (D4 on the board, PG7 on the processor)
	GPIOG->ODR |= ((segmentCode & 0b100 >> 2) << 7);

	// Assigns bit 3 in the 7-segment display sequence to Segment D (D5 on the board, PA8 on the processor)
	GPIOA->ODR = 0 | ((segmentCode & 0b1000 >> 3) << 8);

	// Assigns bit 4 in the 7-segment display sequence to Segment E (D6 on the board, PH6 in the processor)
	GPIOH->ODR = 0 | ((segmentCode & 0b10000 >> 4) << 6);

	// Assigns bit 5 in the 7-segment display sequence to Segment F (D7 on the board, PI3 in the processor)
	GPIOI->ODR = 0 | ((segmentCode & 0b100000 >> 5) << 3);

	// Assigns Bit 6 in the 7-segment display sequence to Segment G (D8 on the board, PI2 on the processor)
	GPIOI->ODR |= ((segmentCode & (0b1 << 6) >> 6) <<2);
}

/**
 * Takes a character and translates it into a set of bits that are used
 * for displaying on a sever-segment display.
 */
int translateCharacter(char theCharacter)
{
	int segmentCode;

	switch (theCharacter){
	case '0':
		segmentCode = 0b0000001;
		break;
	case '1':
		segmentCode = 0b1001111;
		break;
	case '2':
		segmentCode = 0b0010010;
		break;
	case '3':
		segmentCode = 0b0000110;
		break;
	case '4':
		segmentCode = 0b1001100;
		break;
	case '5':
		segmentCode = 0b0100100;
		break;
	case '6':
		segmentCode = 0b0100000;
		break;
	case '7':
		segmentCode = 0b0001101;
		break;
	case '8':
		segmentCode = 0b0000000;
		break;
	case '9':
		segmentCode = 0b0000100;
		break;
	case 'a':
		segmentCode = 0b0001000;
		break;
	case 'd':
		segmentCode = 0b1000010;
		break;
	case 'e':
		segmentCode = 0b0110000;
		break;
	case 'i':
		segmentCode = 0b1001000;
		break;
	case 'r':
		segmentCode = 0b1111010;
		break;
	case 's':
		segmentCode = 0b0100100;
		break;
	case 'u':
		segmentCode = 0b1000001;
		break;
	case 'v':
		segmentCode = 0b0011100;
		break;
	default:
		segmentCode = 255;
		break;
	}

	return segmentCode;
}


void simple_delay(uint32_t count) {
    while (count--) {
        __asm__("NOP");
    }
}
